import sys

def is_pal(s):
    return s == s[::-1]

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    idx = 1
    strings = []
    for _ in range(n):
        s = input[idx]
        c = int(input[idx+1])
        strings.append((s, c))
        idx += 2

    min_single = float('inf')
    for s, c in strings:
        if is_pal(s):
            if c < min_single:
                min_single = c

    min_pair = float('inf')
    for i in range(n):
        for j in range(n):
            s1, c1 = strings[i]
            s2, c2 = strings[j]
            combined1 = s1 + s2
            if is_pal(combined1):
                total = c1 + c2
                if total < min_pair:
                    min_pair = total
            combined2 = s2 + s1
            if is_pal(combined2):
                total = c1 + c2
                if total < min_pair:
                    min_pair = total

    ans = min(min_single, min_pair)
    print(ans if ans != float('inf') else -1)

