def is_palindrome(s):
    return s == s[::-1]

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    strings = []
    cost_dict = {}
    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        idx += 2
        strings.append(s)
        cost_dict[s] = c

    min_cost = float('inf')

    # Check for k=1, 2, 3
    for k in range(1, 4):
        for combo in itertools.product(strings, repeat=k):
            perms = set(itertools.permutations(combo))
            for perm in perms:
                s = ''.join(perm)
                if is_palindrome(s):
                    counts = Counter(perm)
                    total_cost = 0
                    for s_str, count in counts.items():
                        total_cost += count * cost_dict[s_str]
                    if total_cost < min_cost:
                        min_cost = total_cost

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

