    C_list = []
    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        S_list.append(s)
        C_list.append(c)
        idx += 2

    # Case 1: single string is a palindrome
    min_case1 = float('inf')
    for i in range(N):
        if S_list[i] == S_list[i][::-1]:
            if C_list[i] < min_case1:
                min_case1 = C_list[i]

    # Case 2: two strings concatenated form a palindrome
    min_case2 = float('inf')
    for i in range(N):
        for j in range(N):
            combined = S_list[i] + S_list[j]
            if combined == combined[::-1]:
                cost = C_list[i] + C_list[j]
                if cost < min_case2:
                    min_case2 = cost

    # Case 3: left_part and reverse of left_part
    k = 5
    left_dp = {'': 0}
    for _ in range(k):
        temp = {}
        for s in left_dp:
            for i in range(N):
                new_s = s + S_list[i]
                new_cost = left_dp[s] + C_list[i]
                if new_s not in temp or new_cost < temp[new_s]:
                    temp[new_s] = new_cost
        for s in temp:
            if s not in left_dp or temp[s] < left_dp.get(s, float('inf')):
                left_dp[s] = temp[s]

    min_case3 = float('inf')
    for s in left_dp:
        if s == '':
            continue
        reverse_str = s[::-1]
        n = len(reverse_str)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            for j in range(len(S_list)):
                s_j = S_list[j]
                cost_j = C_list[j]
                len_sj = len(s_j)
                if i >= len_sj and reverse_str[i - len_sj:i] == s_j:
                    if dp[i - len_sj] + cost_j < dp[i]:
                        dp[i] = dp[i - len_sj] + cost_j
        if dp[n] < INF:
            total = left_dp[s] + dp[n]
            if total < min_case3:
                min_case3 = total

    candidates = []
    if min_case1 < float('inf'):
        candidates.append(min_case1)
