def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    R = int(data[2])
    S = int(data[3])
    P = int(data[4])
    T = data[5]

    machine_map = {'r': 0, 'p': 1, 's': 2}
    total_score = 0

    for group in range(K):
        group_rounds = [i for i in range(1, N+1) if (i-1) % K == group]
        if not group_rounds:
            continue

        m_moves = []
        for i in group_rounds:
            m_char = T[i-1]
            m_moves.append(machine_map[m_char])

        dp_prev = [0, 0, 0]
        first_m_code = m_moves[0]
        for t_code in range(3):
            if (t_code == 0 and first_m_code == 2) or (t_code == 1 and first_m_code == 0) or (t_code == 2 and first_m_code == 1):
                if t_code == 0:
                    dp_prev[t_code] = R
                elif t_code == 1:
                    dp_prev[t_code] = P
                else:
                    dp_prev[t_code] = S
            else:
                dp_prev[t_code] = 0

        for i in range(1, len(m_moves)):
            current_m_code = m_moves[i]
            dp_current = [0, 0, 0]
            for t_code in range(3):
                max_prev = 0
                for prev_choice in range(3):
                    if prev_choice != t_code:
                        if dp_prev[prev_choice] > max_prev:
                            max_prev = dp_prev[prev_choice]
                if (t_code == 0 and current_m_code == 2) or (t_code == 1 and current_m_code == 0) or (t_code == 2 and current_m_code == 1):
                    if t_code == 0:
                        points = R
                    elif t_code == 1:
                        points = P
                    else:
                        points = S
                else:
                    points = 0
                dp_current[t_code] = max_prev + points
            dp_prev = dp_current

        total_score += max(dp_prev)

    print(total_score)

