def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    R = int(data[2])
    S = int(data[3])
    P = int(data[4])
    T = data[5]

    # Map machine's hand to its value (0: r, 1: p, 2: s)
    m = [0] * N
    for i in range(N):
        if T[i] == 'r':
            m[i] = 0
        elif T[i] == 'p':
            m[i] = 1
        else:
            m[i] = 2

    # Points for each hand choice (0: r, 1: p, 2: s)
    def get_points(machine, hand):
        if (hand - machine) % 3 == 1:
            if hand == 0:
                return R
            elif hand == 1:
                return P
            else:
                return S
        else:
            return 0

    # Initialize DP
    dp = [[0] * 3 for _ in range(N)]

    for i in range(N):
        if i == 0:
            for h in range(3):
                dp[i][h] = get_points(m[i], h)
        else:
            if i < K:
                max_prev = max(dp[i-1])
                for h in range(3):
                    dp[i][h] = max_prev + get_points(m[i], h)
            else:
                prev_step = i - K
                prev_values = dp[prev_step]
                for h in range(3):
                    if h == 0:
                        max_prev = max(prev_values[1], prev_values[2])
                    elif h == 1:
                        max_prev = max(prev_values[0], prev_values[2])
                    else:
                        max_prev = max(prev_values[0], prev_values[1])
                    dp[i][h] = max_prev + get_points(m[i], h)

    print(max(dp[N-1]))

