MOD = 10**9 + 7

def main():
    n, k = map(int, sys.stdin.readline().split())

    @lru_cache(maxsize=None)
    def dfs(mask, current_sum):
        if mask == (1 << n) - 1:
            return 1 if current_sum == k else 0
        m = bin(mask).count('1')
        position = m + 1
        total = 0
        for i in range(n):
            if not (mask & (1 << i)):
                new_mask = mask | (1 << i)
                x = i + 1
                contribution = abs(position - x)
                total += dfs(new_mask, current_sum + contribution)
                total %= MOD
        return total

    result = dfs(0, 0)
    print(result % MOD)

