    n = int(input[0])
    data = list(map(int, input[1:]))
    vectors = []
    for i in range(n):
        x = data[2*i]
        y = data[2*i + 1]
        vectors.append((x, y))

    current_sums = set()
    current_sums.add((0, 0))

    for dx, dy in vectors:
        new_sums = set()
        for (x, y) in current_sums:
            new_sums.add((x + dx, y + dy))
        merged = current_sums.union(new_sums)
        pruned = []
        for pair in merged:
            is_dominated = False
            for p in pruned:
                if p[0]**2 + p[1]**2 >= pair[0]**2 + pair[1]**2:
                    is_dominated = True
                    break
            if not is_dominated:
                to_remove = []
                for i, p in enumerate(pruned):
                    if pair[0]**2 + pair[1]**2 >= p[0]**2 + p[1]**2:
                        to_remove.append(i)
                for i in reversed(to_remove):
                    del pruned[i]
                pruned.append(pair)
        current_sums = set(pruned)

    max_sq = 0
    for (x, y) in current_sums:
        sq = x*x + y*y
        if sq > max_sq:
            max_sq = sq
    result = math.sqrt(max_sq)
    print("{0:.20f}".format(result))

