        new_points = [(px + x, py + y) for (px, py) in points]
        all_points = points + new_points
        hull = convex_hull(all_points)
        points = hull
    max_dist = 0.0
    for (x, y) in points:
        dist = math.hypot(x, y)
        if dist > max_dist:
            max_dist = dist
    print("{0:.20f}".format(max_dist))

