    data = input().split()

    n = int(data[0])
    vectors = []
    index = 1
    for _ in range(n):
        x = int(data[index])
        y = int(data[index + 1])
        vectors.append((x, y))
        index += 2

    directions = set()

    # Add all individual vectors as directions
    for x, y in vectors:
        directions.add((x, y))

    # Add all pairwise sums
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = vectors[i]
            x2, y2 = vectors[j]
            directions.add((x1 + x2, y1 + y2))

    # Add the sum of all vectors
    sum_all_x = sum(x for x, y in vectors)
    sum_all_y = sum(y for x, y in vectors)
    directions.add((sum_all_x, sum_all_y))

    max_distance_squared = 0.0

    for a, b in directions:
        current_sum_x = 0
        current_sum_y = 0
        for x, y in vectors:
            proj = x * a + y * b
            if proj > 0:
                current_sum_x += x
                current_sum_y += y
        distance_squared = current_sum_x ** 2 + current_sum_y ** 2
        if distance_squared > max_distance_squared:
            max_distance_squared = distance_squared

    # Also consider the case where no vectors are selected
    if max_distance_squared == 0:
        print("0.000000000000000000000000000000000000000000000000")
    else:
        max_distance = math.sqrt(max_distance_squared)
        print("{0:.20f}".format(max_distance))

