    if k == 0:
        return False
    for i in range(k):
        u = cycle[i]
        next_node = cycle[(i+1) % k]
        for v in out_edges[u]:
            if v in cycle:
                if v != next_node:
                    return False
    for i in range(k):
        u = cycle[i]
