def find_cycle(adj, in_edges, out_edges, N):
    visited = [False] * (N + 1)
    for u in range(1, N+1):
        if not visited[u]:
            stack = [(u, False)]  # (node, is_processed)
            path = []
            rec_stack = []
            path_map = {}
            while stack:
                node, is_processed = stack.pop()
                if is_processed:
                    # Process the node after its children
                    rec_stack.pop()
                    path.pop()
                    continue
                if visited[node]:
                    continue
                visited[node] = True
                path.append(node)
                path_map[node] = len(path) - 1
                rec_stack.append(node)
                # Push the node back with is_processed=True
                stack.append((node, True))
                # Push children
                for v in reversed(adj[node]):
                    if not visited[v]:
                        stack.append((v, False))
                    elif v in rec_stack:
                        # Found a cycle
                        idx = rec_stack.index(v)
                        current_cycle = rec_stack[idx:]
                        if is_valid_cycle(current_cycle, out_edges, in_edges):
                            return current_cycle
    return None

