    cnt = [0] * (max_bit + 1)
    for num in A:
        for bit in range(max_bit + 1):
            if num & (1 << bit):
                cnt[bit] += 1

    @lru_cache(maxsize=None)
    def dfs(pos, tight):
        if pos == -1:
            return 0
        res = 0
        max_bit_val = (K >> pos) & 1 if tight else 1
        for b in [0, 1]:
            if tight and b > max_bit_val:
                continue
            new_tight = tight and (b == max_bit_val)
            if b == 0:
                contrib = cnt[pos] * (1 << pos)
            else:
                contrib = (N - cnt[pos]) * (1 << pos)
            res = max(res, contrib + dfs(pos - 1, new_tight))
        return res

    print(dfs(max_bit, True))

