def count_subsets(t, m):
    if t < 0:
        return 0
    t_bin = bin(t)[2:]
    m_bin = bin(m)[2:]
    m_len = len(t_bin)
    m_padded = m & ((1 << m_len) - 1)
    t_padded = t

    @lru_cache(maxsize=None)
    def dfs(pos, is_tight, leading_zero):
        if pos == m_len:
            return 1
        res = 0
        max_bit = 1 if is_tight else 1
        t_bit = (t_padded >> (m_len - 1 - pos)) & 1
        m_bit = (m_padded >> (m_len - 1 - pos)) & 1
        for bit in [0, 1]:
            if bit > m_bit:
                continue
            new_is_tight = is_tight and (bit == t_bit)
            new_leading_zero = leading_zero and (bit == 0)
            res += dfs(pos + 1, new_is_tight, new_leading_zero)
        return res

    return dfs(0, True, True)

