MOD = 10**9 + 7

def count_set(x, k):
    if x < 0:
        return 0
    s = bin(x)[2:]
    n = len(s)

    @lru_cache(maxsize=None)
    def dp(pos, cnt, tight):
        if pos == n:
            return 1 if cnt == k else 0
        limit = int(s[pos]) if tight else 1
        res = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_cnt = cnt + (d == 1)
            res += dp(pos + 1, new_cnt, new_tight)
        return res

    return dp(0, 0, True)

def main():
    L, R = map(int, sys.stdin.readline().split())
    ans = 0
    for m in range(1, 61):
        a = 1 << (m - 1)
        b = (1 << m) - 1
        low = max(L, a)
        high = min(R, b)
        if low > high:
            continue
        for k in range(1, m + 1):
            c_high = count_set(high, k)
            c_low = count_set(low - 1, k)
            cnt = c_high - c_low
            if cnt < 0:
                cnt = 0
            exponent = m - k
            term = cnt * pow(2, exponent, MOD)
            ans = (ans + term) % MOD
    print(ans)

