def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    M_a = int(input[idx]); idx += 1
    M_b = int(input[idx]); idx += 1
    packages = []
    for _ in range(N):
        a = int(input[idx]); idx += 1
        b = int(input[idx]); idx += 1
        c = int(input[idx]); idx += 1
        packages.append((a, b, c))

    mid = N // 2
    left = packages[:mid]
    right = packages[mid:]

    def generate_subsets(packages):
        n = len(packages)
        subsets = []
        for mask in range(1 << n):
            sum_s = 0
            sum_cost = 0
            for i in range(n):
                if mask & (1 << i):
                    a, b, c = packages[i]
                    sum_s += a * M_b - b * M_a
                    sum_cost += c
            subsets.append((sum_s, sum_cost))
        return subsets

    left_subsets = generate_subsets(left)
    right_subsets = generate_subsets(right)

    right_dict = {}
    for s, cost in right_subsets:
        if s not in right_dict or cost < right_dict[s]:
            right_dict[s] = cost

    min_total = float('inf')
    for s_left, cost_left in left_subsets:
        target = -s_left
        if target in right_dict:
            total_cost = cost_left + right_dict[target]
            if total_cost != 0:
                if total_cost < min_total:
                    min_total = total_cost

    if min_total == float('inf'):
        print(-1)
    else:
        print(min_total)

