        groups = []
        start = 0
        for pos in split_positions:
            groups.append((start, pos))
            start = pos + 1
        groups.append((start, H - 1))
        h = len(groups)

        # Compute col_sums for each column
        col_sums = []
        for j in range(W):
            sums = []
            for (start_row, end_row) in groups:
                total = prefix[j][end_row + 1] - prefix[j][start_row]
                sums.append(total)
            col_sums.append(sums)

        # Compute vertical cuts
        current_sums = [0] * h
        vertical_cuts = 0
        for j in range(W):
            temp_sums = [current_sums[i] + col_sums[j][i] for i in range(h)]
            valid = True
            for val in temp_sums:
                if val > K:
                    valid = False
                    break
            if valid:
                current_sums = temp_sums
            else:
                vertical_cuts += 1
                current_sums = [col_sums[j][i] for i in range(h)]

        total_cuts = bin(bitmask).count('1') + vertical_cuts
        if total_cuts < min_total:
            min_total = total_cuts

