from itertools import product

def main():
    H, W, K = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(H):
        line = sys.stdin.readline().strip()
        grid.append([int(c) for c in line])

    min_cuts = float('inf')

    # Generate all possible row splits
    for split in product([True, False], repeat=H-1):
        # Generate row groups
        row_groups = []
        start = 0
        for i in range(H-1):
            if split[i]:
                row_groups.append(list(range(start, i+1)))
                start = i + 1
        row_groups.append(list(range(start, H)))

        num_row_groups = len(row_groups)
        # Compute column_sums for each row group
        column_sums = [[0]*W for _ in range(num_row_groups)]
        for r in range(num_row_groups):
            rows_in_group = row_groups[r]
            for j in range(W):
                total = 0
                for row in rows_in_group:
                    total += grid[row][j]
                column_sums[r][j] = total

        # Compute vertical cuts
        current_sums = [0] * num_row_groups
        vertical_cuts = 0
        for j in range(W):
            # Check if adding column j is possible
            can_add = True
            for r in range(num_row_groups):
                if current_sums[r] + column_sums[r][j] > K:
                    can_add = False
                    break
            if can_add:
                for r in range(num_row_groups):
                    current_sums[r] += column_sums[r][j]
            else:
                vertical_cuts += 1
                # Reset current_sums
                for r in range(num_row_groups):
                    current_sums[r] = column_sums[r][j]

        # Calculate total cuts
        horizontal_cuts = sum(split)
        total_cuts = horizontal_cuts + vertical_cuts
        if total_cuts < min_cuts:
            min_cuts = total_cuts

    print(min_cuts)

