def main():
    import sys
    H, W, K = map(int, sys.stdin.readline().split())

    def is_valid(mask):
        return (mask & (mask << 1)) == 0

    # Generate all valid configurations
    configs = []
    for mask in range(0, 1 << (W-1)):
        if is_valid(mask):
            configs.append(mask)

    # Initialize DP
    dp = [0] * (W + 1)
    dp[1] = 1

    for _ in range(H):
        new_dp = [0] * (W + 1)
        for config in configs:
            for prev_pos in range(1, W + 1):
                if dp[prev_pos] == 0:
                    continue
                i = prev_pos
                left_line = False
                if i > 1:
                    left_bit = i - 2
                    if (config >> left_bit) & 1:
                        left_line = True
                right_line = False
                if i < W:
                    right_bit = i - 1
                    if (config >> right_bit) & 1:
                        right_line = True
                if left_line:
                    new_pos = i - 1
                elif right_line:
                    new_pos = i + 1
                else:
                    new_pos = i
                new_dp[new_pos] = (new_dp[new_pos] + dp[prev_pos]) % MOD
        dp = new_dp

    print(dp[K] % MOD)

