def main():
    import sys
    input = sys.stdin.read
    N, X = map(int, input().split())

    layers = [0] * (N + 1)
    patties = [0] * (N + 1)
    layers[0] = 1
    patties[0] = 1

    for l in range(1, N + 1):
        layers[l] = 2 * layers[l-1] + 3
        patties[l] = 2 * patties[l-1] + 1

    def count_patties(L, X):
        if L == 0:
            return 1 if X >= 1 else 0
        if X == 0:
            return 0
        if X == 1:
            return 0
        if X <= 1 + layers[L-1]:
            return count_patties(L-1, X-1)
        elif X == 1 + layers[L-1] + 1:
            return patties[L-1] + 1
        elif X <= 1 + layers[L-1] + 1 + layers[L-1]:
            return patties[L-1] + 1 + count_patties(L-1, X - (1 + layers[L-1] + 1))
        else:
            return patties[L]

    print(count_patties(N, X))

