class DSU:
    def __init__(self, n):
        self.parent = list(range(n+1))
        self.parity = [0]*(n+1)
        self.rank = [1]*(n+1)

    def find(self, x):
        if self.parent[x] != x:
            orig_parent = self.parent[x]
            root, p = self.find(orig_parent)
            self.parent[x] = root
            self.parity[x] ^= p
        return self.parent[x], self.parity[x]

    def union(self, x, y, c):
        root_x, p_x = self.find(x)
        root_y, p_y = self.find(y)
        if root_x == root_y:
            return
        if self.rank[root_x] > self.rank[root_y]:
            root_x, root_y = root_y, root_x
            p_x, p_y = p_y, p_x
        self.parent[root_x] = root_y
        d = (c - p_x - p_y) % 2
        self.parity[root_x] = d
        if self.rank[root_x] == self.rank[root_y]:
            self.rank[root_y] += 1

