        A.append(row)
        idx += N

    # Check validity of the distance matrix
    for i in range(N):
        for j in range(N):
            for k in range(N):
                if A[i][j] + A[j][k] < A[i][k]:
                    print(-1)
                    return

    # Generate all edges (i, j) with i < j
    edges = []
    for i in range(N):
        for j in range(i + 1, N):
            edges.append((A[i][j], i, j))

    # Sort edges by weight
    edges.sort()

    # Kruskal's algorithm to find MST
    uf = UnionFind(N)
    total = 0
    for w, u, v in edges:
        if uf.find(u) != uf.find(v):
            uf.unite(u, v)
            total += w

    print(total)

