    def dfs(i, x_val, y_val, turn):
        if i == N:
            return abs(x_val - y_val)
        if turn == 0:  # X's turn
            max_score = -1
            for k in range(1, N - i + 1):
                new_i = i + k
                new_x = a[i + k - 1]
                score = dfs(new_i, new_x, y_val, 1)
                if score > max_score:
                    max_score = score
            return max_score
        else:  # Y's turn
            min_score = float('inf')
            for l in range(1, N - i + 1):
                new_i = i + l
                new_y = a[i + l - 1]
                score = dfs(new_i, x_val, new_y, 0)
                if score < min_score:
                    min_score = score
            return min_score

    result = dfs(0, Z, W, 0)
    print(result)

