    for group in groups:
        group.sort(reverse=True)
        prefix = [0]
        for val in group:
            prefix.append(prefix[-1] + val)
        group_prefix.append(prefix)

    binary_items = []
    for group_idx in range(4):
        group = groups[group_idx]
        m = len(group)
        prefix = group_prefix[group_idx]
        current = 1
        while current <= m:
            binary_items.append((group_idx, current, prefix[current]))
            m -= current
            current *= 2
        if m > 0:
            binary_items.append((group_idx, m, prefix[m]))

    max_total = 0
    for k in range(0, N+1):
        a = w1
        total_weight = a * k
