        if new_capacity < 0:
            continue

        dp = [[-float('inf')] * (new_capacity + 1) for _ in range(k+1)]
        dp[0][0] = 0

        for (group_idx, t, value) in binary_items:
            weight = t * group_idx
            for i in range(k, -1, -1):
                for j in range(new_capacity, -1, -1):
                    if dp[i][j] == -float('inf'):
