def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    strings = input[1:N+1]

    total_open = 0
    total_close = 0
    for s in strings:
        total_open += s.count('(')
        total_close += s.count(')')

    if total_open != total_close:
        print("No")
        return

    positive = []
    negative = []
    zero = []

    for s in strings:
        balance = 0
        min_balance = 0
        max_balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:
                balance -= 1
            min_balance = min(min_balance, balance)
            max_balance = max(max_balance, balance)
        delta = balance
        if delta > 0:
            positive.append((min_balance, max_balance, delta))
        elif delta < 0:
            negative.append((min_balance, max_balance, delta))
        else:
            zero.append((min_balance, max_balance, delta))

    positive.sort(key=lambda x: x[0])
    negative.sort(key=lambda x: -x[1])
    zero.sort(key=lambda x: x[0])

    combined = positive + zero + negative
    current_balance = 0
    for min_b, _, delta in combined:
        if current_balance + min_b < 0:
            print("No")
            return
