    for i in range(N):
        x_left = points[i][0]
        for j in range(i, N):
            x_right = points[j][0]
            current_ys = []
            for k in range(N):
                if x_left <= points[k][0] <= x_right:
                    current_ys.append(points[k][1])
            if len(current_ys) < K:
                continue
            current_ys.sort()
            min_y_diff = float('inf')
            for start in range(len(current_ys) - K + 1):
                end = start + K - 1
                y_diff = current_ys[end] - current_ys[start]
                if y_diff < min_y_diff:
                    min_y_diff = y_diff
            area = (x_right - x_left) * min_y_diff
            if area < min_area:
                min_area = area

    print(min_area)

