def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    s = list(map(int, data[1:N+1]))

    max_score = 0

    for t in range(0, 100):
        if t == 0:
            # Case where the game ends after 1 step
            A = N - 1
            score = 0
            if max_score < score:
                max_score = score
        else:
            r = (N - 1) % t
            min_A = (N - 1 + t) // (t + 1)
            for A in range(min_A, N):
                if A % t != r:
                    continue
                numerator = (t + 1) * A - (N - 1)
                if numerator % t != 0:
                    continue
                B = numerator // t
                if B <= 0:
                    continue
                # Check positions
                positions = set()
                valid = True
                for i in range(0, 2 * t + 1):
                    k_add = (i + 1) // 2
                    k_sub = i // 2
                    pos = k_add * A - k_sub * B
                    if pos < 0 or pos >= N:
                        valid = False
                        break
                    if pos in positions:
                        valid = False
                        break
                    positions.add(pos)
                if valid:
                    # Compute score
                    score = 0
                    for i in range(1, 2 * t + 1):
                        k_add = (i + 1) // 2
                        k_sub = i // 2
                        pos = k_add * A - k_sub * B
                        score += s[pos]
                    if score > max_score:
                        max_score = score
    print(max_score)

