import heapq

def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    H = int(input[ptr])
    ptr += 1
    W = int(input[ptr])
    ptr += 1

    c = []
    for _ in range(10):
        row = list(map(int, input[ptr:ptr+10]))
        ptr += 10
        c.append(row)

    # Build reversed adjacency list
    reversed_adj = [[] for _ in range(10)]
    for i in range(10):
        for j in range(10):
            cost = c[i][j]
            reversed_adj[j].append((i, cost))

    # Dijkstra's algorithm from node 1 in reversed graph
    INF = float('inf')
    dist = [INF] * 10
    dist[1] = 0
    heap = [(0, 1)]

    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, cost in reversed_adj[u]:
            if dist[v] > dist[u] + cost:
                dist[v] = dist[u] + cost
                heapq.heappush(heap, (dist[v], v))

    # Read wall data
    wall = []
    for _ in range(H):
        row = list(map(int, input[ptr:ptr+W]))
        ptr += W
        wall.append(row)

    total = 0
    for i in range(H):
        for j in range(W):
            val = wall[i][j]
            if val != -1:
                total += dist[val]

    print(total)

