    neg = []
    zeros = []
    pos = []
    for num in A:
        if num < 0:
            neg.append(num)
        elif num == 0:
            zeros.append(num)
        else:
            pos.append(num)
    low = -10**18
    high = 10**18
    while low < high:
        mid = (low + high) // 2
        cnt = 0
        len_neg = len(neg)
        len_zero = len(zeros)
        len_pos = len(pos)
        # part1: neg-neg
        if mid >= 0:
            for i in range(len_neg):
                low_i = i + 1
                high_i = len_neg - 1
                best_j = i
                while low_i <= high_i:
                    mid_i = (low_i + high_i) // 2
                    product = neg[i] * neg[mid_i]
                    if product <= mid:
                        best_j = mid_i
                        low_i = mid_i + 1
                    else:
                        high_i = mid_i - 1
                cnt += (best_j - i)
        # part2: zero-zero
        if mid >= 0:
            cnt += len_zero * (len_zero - 1) // 2
        # part3: zero-pos
        if mid >= 0:
            cnt += len_zero * len_pos
        # part4: neg-zero
        if mid >= 0:
            cnt += len_neg * len_zero
        # part5: neg-pos
        if mid < 0:
            for a in neg:
                threshold = math.ceil(mid / a)
                idx = bisect.bisect_left(pos, threshold)
                cnt += len_pos - idx
        # part6: pos-pos
        if mid >= 0:
            for i in range(len_pos):
                low_i = i + 1
                high_i = len_pos - 1
                best_j = i
                while low_i <= high_i:
