                    product = pos[i] * pos[mid_i]
                    if product <= mid:
                        best_j = mid_i
                        low_i = mid_i + 1
                    else:
                        high_i = mid_i - 1
                cnt += (best_j - i)
        if cnt >= K:
            high = mid
        else:
            low = mid + 1
    print(low)

