        for x, y in L_points:
            static_y.append(y)
        max_static_y = max(static_y)
        min_static_y = min(static_y)

    critical_times = set()

    # Generate critical times for max_x
    if R_points and L_points:
        t = (max_x_L - max_x_R) / 2.0
        if t >= 0:
