    points = []
    for _ in range(N):
        x = int(input[idx])
        y = int(input[idx+1])
        d = input[idx+2]
        points.append((x, y, d))
        idx += 3

    def compute_value(t):
        x_values = []
        y_values = []
        for x, y, d in points:
            if d == 'R':
                x_t = x + t
            elif d == 'L':
                x_t = x - t
            else:
                x_t = x
            x_values.append(x_t)
            if d == 'U':
                y_t = y + t
            elif d == 'D':
                y_t = y - t
            else:
                y_t = y
            y_values.append(y_t)
        x_max = max(x_values)
        x_min = min(x_values)
        y_max = max(y_values)
        y_min = min(y_values)
        return (x_max - x_min) * (y_max - y_min)

    low = 0.0
    high = 1e14
    for _ in range(100):
        if high - low < 1e-9:
            break
        mid1 = low + (high - low)/3
        mid2 = high - (high - low)/3
        f1 = compute_value(mid1)
        f2 = compute_value(mid2)
        if f1 < f2:
            high = mid2
        else:
            low = mid1

    candidates = [low, high, (low + high)/2, 0.0]
    min_val = float('inf')
    for t in candidates:
        val = compute_value(t)
        if val < min_val:
            min_val = val
    print(min_val)

