    def find_min_quad(a, b, c, t_low, t_high):
        # a*t^2 + b*t + c
        if a == 0:
            # linear function
            if b == 0:
                return c
            else:
                val_low = a * t_low**2 + b * t_low + c
                val_high = a * t_high**2 + b * t_high + c
                return min(val_low, val_high)
        else:
            vertex = -b / (2 * a)
            if vertex < t_low:
                val_low = a * t_low**2 + b * t_low + c
                val_high = a * t_high**2 + b * t_high + c
                return min(val_low, val_high)
            elif vertex > t_high:
                val_low = a * t_low**2 + b * t_low + c
                val_high = a * t_high**2 + b * t_high + c
                return min(val_low, val_high)
            else:
                val_vertex = a * vertex**2 + b * vertex + c
                val_low = a * t_low**2 + b * t_low + c
                val_high = a * t_high**2 + b * t_high + c
                return min(val_vertex, val_low, val_high)

