            val = min_fixed_y
            terms_y_min.append( (val, 0, min_fixed_y) )
        y_min_val = min( [t[0] for t in terms_y_min] )
        for term in terms_y_min:
            if term[0] == y_min_val:
                a_y_min, b_y_min = term[1], term[2]
                break

        # Compute x_range and y_range as linear functions
        a_x = a_x_max - a_x_min
        b_x = b_x_max - b_x_min
        a_y = a_y_max - a_y_min
        b_y = b_y_max - b_y_min

        # Compute quadratic coefficients
        a_quad = a_x * a_y
        b_quad = a_x * b_y + a_y * b_x
        c_quad = b_x * b_y

        # Find minimum in [t_prev, t_current]
        current_min = find_min_quad(a_quad, b_quad, c_quad, t_prev, t_current)
        if current_min < min_area:
            min_area = current_min

    print("{0:.10f}".format(min_area))

