        for i in reversed(range(60)):
            if (x >> i) & 1:
                if self.basis[i] == 0:
                    self.basis[i] = x
                    return True
                else:
                    x ^= self.basis[i]
        return False

    def max_xor(self):
        res = 0
        for i in reversed(range(60)):
            if self.basis[i] and (res ^ self.basis[i]) > res:
                res ^= self.basis[i]
        return res

