MOD = 10**9 + 7

def main():
    N = int(sys.stdin.readline())
    if N == 0:
        print(1)
        return

    # Convert N to binary, highest bit first
    bits = []
    while N > 0:
        bits.append(N & 1)
        N >>= 1
    bits = bits[::-1]
    m = len(bits)

    # dp[i][s] = number of ways to process first i bits with state s
    # s=0: sum is less than N's prefix
    # s=1: sum is equal to N's prefix
    # s=2: sum is greater than N's prefix
    dp = [[0] * 3 for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(m):
        current_bit = bits[i]
        for s in range(3):
            if dp[i][s] == 0:
                continue
            # Try all possible choices for this bit
            # Choice 1: include in u (contribution 2^i)
            # Choice 2: include in k (contribution 2^(i+1))
            # Choice 3: include in neither (contribution 0)
            for choice in [1, 2, 3]:
                if choice == 1:
                    contribution = 1 << i
                elif choice == 2:
                    contribution = 1 << (i + 1)
                else:
                    contribution = 0

                # Determine new state
                if s == 0:
                    # Current sum is less than N's prefix, any choice is allowed
                    new_s = 0
                elif s == 1:
                    # Current sum is equal to N's prefix, check if contribution exceeds current_bit
                    if contribution > (current_bit << i):
                        new_s = 2
                    elif contribution == (current_bit << i):
                        new_s = 1
                    else:
                        new_s = 0
                else:
                    # Current sum is greater, no need to check
                    new_s = 2

                dp[i+1][new_s] = (dp[i+1][new_s] + dp[i][s]) % MOD

    # The answer is the sum of ways where the sum is less than or equal to N
    result = (dp[m][0] + dp[m][1]) % MOD
    print(result)

