def main():
    H, W, K = map(int, sys.stdin.readline().split())
    x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    # Preprocess len_left, len_right, len_up, len_down
    len_left = [[0]*W for _ in range(H)]
    len_right = [[0]*W for _ in range(H)]
    len_up = [[0]*W for _ in range(H)]
    len_down = [[0]*W for _ in range(H)]

    # Compute len_left
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '@':
                len_left[i][j] = 0
            else:
                if j == 0:
                    len_left[i][j] = 1
                else:
                    len_left[i][j] = len_left[i][j-1] + 1

    # Compute len_right
    for i in range(H):
        for j in range(W-1, -1, -1):
            if grid[i][j] == '@':
                len_right[i][j] = 0
            else:
                if j == W-1:
                    len_right[i][j] = 1
                else:
                    len_right[i][j] = len_right[i][j+1] + 1

    # Compute len_up
    for j in range(W):
        for i in range(H):
            if grid[i][j] == '@':
                len_up[i][j] = 0
            else:
                if i == 0:
                    len_up[i][j] = 1
                else:
                    len_up[i][j] = len_up[i-1][j] + 1

    # Compute len_down
    for j in range(W):
        for i in range(H-1, -1, -1):
            if grid[i][j] == '@':
                len_down[i][j] = 0
            else:
                if i == H-1:
                    len_down[i][j] = 1
                else:
                    len_down[i][j] = len_down[i+1][j] + 1

    # BFS
    distance = [[-1]*W for _ in range(H)]
    start_i = x1 - 1
    start_j = y1 - 1
    end_i = x2 - 1
    end_j = y2 - 1

    distance[start_i][start_j] = 0
    q = deque()
    q.append( (start_i, start_j) )

    while q:
        i, j = q.popleft()

        # West
        steps_west = len_left[i][j] - 1
        steps_to_take = min(K, steps_west)
        if steps_to_take > 0:
            new_j = j - steps_to_take
            if new_j >= 0 and distance[i][new_j] == -1:
                distance[i][new_j] = distance[i][j] + 1
                q.append( (i, new_j) )

        # East
        steps_east = len_right[i][j] - 1
        steps_to_take = min(K, steps_east)
        if steps_to_take > 0:
            new_j = j + steps_to_take
            if new_j < W and distance[i][new_j] == -1:
                distance[i][new_j] = distance[i][j] + 1
                q.append( (i, new_j) )

        # North
        steps_north = len_up[i][j] - 1
        steps_to_take = min(K, steps_north)
        if steps_to_take > 0:
            new_i = i - steps_to_take
            if new_i >= 0 and distance[new_i][j] == -1:
                distance[new_i][j] = distance[i][j] + 1
                q.append( (new_i, j) )

        # South
        steps_south = len_down[i][j] - 1
        steps_to_take = min(K, steps_south)
        if steps_to_take > 0:
            new_i = i + steps_to_take
            if new_i < H and distance[new_i][j] == -1:
                distance[new_i][j] = distance[i][j] + 1
                q.append( (new_i, j) )

    print(distance[end_i][end_j] if distance[end_i][end_j] != -1 else -1)

