import math

MOD = 10**9 + 7

def normalize(a, b):
    if a == 0 and b == 0:
        return None
    g = math.gcd(abs(a), abs(b))
    x = a // g
    y = b // g
    if x == 0:
        if y < 0:
            y = -y
    else:
        if x < 0:
            x = -x
            y = -y
    return (x, y)

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    zero_count = 0
    direction_counts = dict()
    for _ in range(N):
        a = int(input[idx])
        b = int(input[idx + 1])
        idx += 2
        if a == 0 and b == 0:
            zero_count += 1
        else:
            d = normalize(a, b)
            if d in direction_counts:
                direction_counts[d] += 1
            else:
                direction_counts[d] = 1
    product_non_zero = 1
    processed = set()
    for d in direction_counts:
        if d not in processed:
            x, y = d
            perp_x = y
            perp_y = -x
            perp_d = normalize(perp_x, perp_y)
            if perp_d in direction_counts and perp_d not in processed:
                count_d = direction_counts[d]
                count_perp = direction_counts[perp_d]
                term1 = pow(2, count_d, MOD)
                term2 = pow(2, count_perp, MOD)
                term = (term1 * term2) % MOD
                term -= ((term1 - 1) * (term2 - 1)) % MOD
                term %= MOD
                product_non_zero = (product_non_zero * term) % MOD
                processed.add(d)
                processed.add(perp_d)
            else:
                count_d = direction_counts[d]
                term = pow(2, count_d, MOD)
                product_non_zero = (product_non_zero * term) % MOD
                processed.add(d)
    answer = (product_non_zero - 1 + zero_count) % MOD
    print(answer)

