def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1

    S = list(map(int, input[idx:idx+N]))
    idx += N
    T = list(map(int, input[idx:idx+N]))
    idx += N
    U = list(map(int, input[idx:idx+N]))
    idx += N
    V = list(map(int, input[idx:idx+N]))
    idx += N

    row_and = [None] * N
    row_or = [None] * N
    for i in range(N):
        if S[i] == 0:
            row_and[i] = U[i]
        else:
            row_or[i] = U[i]

    column_and = [None] * N
    column_or = [None] * N
    for j in range(N):
        if T[j] == 0:
            column_and[j] = V[j]
        else:
            column_or[j] = V[j]

    a = [[0]*N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            lower = 0
            if row_and[i] is not None:
                lower = max(lower, row_and[i])
            if column_and[j] is not None:
                lower = max(lower, column_and[j])
            upper = (1 << 64) - 1
            if row_or[i] is not None:
                upper = min(upper, row_or[i])
            if column_or[j] is not None:
                upper = min(upper, column_or[j])
            if lower > upper:
                print(-1)
                return
            a[i][j] = lower

    # Adjust rows with S[i] = 1
    for i in range(N):
        if S[i] == 1:
            current_or = 0
            for j in range(N):
                current_or |= a[i][j]
            if current_or != U[i]:
                a[i][0] = U[i]

    # Adjust columns with T[j] = 1
    for j in range(N):
        if T[j] == 1:
            current_or = 0
            for i in range(N):
                current_or |= a[i][j]
            if current_or != V[j]:
                a[0][j] = V[j]

    # Check rows
    for i in range(N):
        if S[i] == 0:
            current_and = a[i][0]
            for j in range(1, N):
                current_and &= a[i][j]
            if current_and != U[i]:
                print(-1)
                return
        else:
            current_or = a[i][0]
            for j in range(1, N):
                current_or |= a[i][j]
            if current_or != U[i]:
                print(-1)
                return

    # Check columns
    for j in range(N):
        if T[j] == 0:
            current_and = a[0][j]
            for i in range(1, N):
                current_and &= a[i][j]
            if current_and != V[j]:
                print(-1)
                return
        else:
            current_or = a[0][j]
            for i in range(1, N):
                current_or |= a[i][j]
            if current_or != V[j]:
                print(-1)
                return

    for row in a:
        print(' '.join(map(str, row)))

